test('createInvoice tier discount and VAT affect invoice totals', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  const lineTotal = 10 * 8500;
  const expectedDiscount = lineTotal * 0.05;
  const amountAfterDiscount = lineTotal - expectedDiscount;
  const expectedVat = Math.round(amountAfterDiscount * 0.21);
  assert.equal(totals.subtotal, lineTotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, lineTotal - expectedDiscount + expectedVat);
});

test('lineVat calculates VAT on amount after discount', () => {
