    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(r.ok, true);
  const r2 = applyVoucher(r.value, { code: 'SUMMER20', amount: 5000 });
  assert.equal(r2.ok, true);
