test('invoiceTotals calculates discount and VAT from tier', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'LOGO-PACK', qty: 2 },
    ],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  const lineTotal1 = 8 * 8500;
  const lineTotal2 = 2 * 120000;
  const subtotal = lineTotal1 + lineTotal2;
  const discount1 = lineTotal1 * 0.05;
  const discount2 = lineTotal2 * 0.05;
  const discount = discount1 + discount2;
  const amountAfterDiscount1 = lineTotal1 - discount1;
  const amountAfterDiscount2 = lineTotal2 - discount2;
  const vat1 = Math.round(amountAfterDiscount1 * 0.21);
  const vat2 = Math.round(amountAfterDiscount2 * 0.21);
  const vat = vat1 + vat2;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal - discount + vat);
});

