  const totals = invoiceTotals(invoice);
  // Each line: 100 * 0.21 = 21
  // Total VAT: 21 + 21 + 21 = 63
  assert.equal(totals.vat, 63);
});

test('createInvoice with VAT on discounted line', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  // DES-HOUR: 10 * 8500 = 85000
  // Discount (10%): 8500
  // Amount after discount: 76500
  // VAT (21%): 16065
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 8500);
  assert.equal(totals.vat, 16065);
  assert.equal(totals.total, 85000 - 8500 + 16065);
});

